        sb.append("line: ");
        // should be 1-based, but consider -1 to be canonical "got none"
        if (_lineNr >= 0) {
            sb.append(_lineNr);
        } else {
            sb.append("UNKNOWN");
        }
        sb.append(", column: ");
        if (_columnNr >= 0) { // same here
            sb.append(_columnNr);
        } else {
            sb.append("UNKNOWN");
        }
    } else {
        // For non-textual content, use byte offset
        sb.append("byte offset: #");
        // For binary formats, total bytes should be the canonical offset
        // for token/current location
        if (_totalBytes >= 0) {
            sb.append(_totalBytes);
        } else {
            sb.append("UNKNOWN");
        }
    }
    return sb;
}

